class Solution {
public:
    vector<bool> isArraySpecial(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        vector<int> pref(n, 0);
        for (int i = 1; i < n; ++i) {
            pref[i] = pref[i - 1] + ((nums[i] % 2) == (nums[i - 1] % 2) ? 1 : 0);
        }
        vector<bool> ans;
        for (const auto& q : queries) {
            ans.push_back((pref[q[1]] - pref[q[0]]) == 0);
        }
        return ans;
    }
};

class Solution {
    public boolean[] isArraySpecial(int[] nums, int[][] queries) {
        int n = nums.length;
        int[] pref = new int[n];
        for (int i = 1; i < n; i++) {
            pref[i] = pref[i - 1] + (nums[i] % 2 == nums[i - 1] % 2 ? 1 : 0);
        }
        boolean[] ans = new boolean[queries.length];
        for (int i = 0; i < queries.length; i++) {
            ans[i] = (pref[queries[i][1]] - pref[queries[i][0]]) == 0;
        }
        return ans;
    }
}

var isArraySpecial = function(nums, queries) {
    const n = nums.length;
    const pref = new Array(n).fill(0);
    for (let i = 1; i < n; i++) {
        pref[i] = pref[i - 1] + (nums[i] % 2 === nums[i - 1] % 2 ? 1 : 0);
    }
    return queries.map(([f, t]) => (pref[t] - pref[f]) === 0);
};
